{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "The highest-similarity analogue, a fused morpholine-pyrimidine with an aminopyridine substituent, showed minimal brain levels after oral dosing in rats, directly indicating poor CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A closely related analogue bearing the same aminopyrimidine motif and fused bicyclic core had minimal brain exposure (total brain AUC0-8 = 104 ng·h/g) after oral dosing in rats, supporting poor brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "CLR457, a morpholine-containing pyrimidine with an aminopyrimidine-like heteroaryl, had a brain/plasma AUC ratio of 0.07, indicating minimal CNS penetration and supporting the fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A more lipophilic morpholine-pyrimidine PET ligand showed measurable brain uptake (brain/blood ratio 0.5), but its tert-butyl and amide modifications and fast brain clearance limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "A smaller morpholine-pyrimidine PET tracer reached brain SUV 2.8, demonstrating that this heteroaryl motif can be brain penetrant, but its lower similarity and simpler lipophilic scaffold reduce weight against the close poor-penetration analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Weighing the closest structural analogues (fused morpholine/pyrimidine with aminoheteroaryl) that show minimal brain exposure, together with the low passive-permeability prior, the query is predicted to lack meaningful CNS access. The few brain-penetrant analogues are less similar and carry lipophilic modifications absent in the query.",
  "evidence_gaps": [
    "No direct experimental brain/plasma or CSF data for the query molecule.",
    "No data in brain tumor/glioma models, where BBB integrity may be altered.",
    "Efflux transporter substrate status (P-gp/BCRP) is not experimentally defined.",
    "Good-penetration evidence comes from PET tracers with lower structural similarity and different physicochemical profiles."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

